public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    if (session == null) {
        throw new NullPointerException("session");
    }
    if (lb == null) {
        throw new NullPointerException("lb");
    }

    int length = str.length();
    if (length == 0) {
        return lb;
    }

    // Estimate the number of bytes needed for UTF-8 encoding
    int estimatedBytes = length;
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c > 0x7F) {
            estimatedBytes++;
            if (c > 0x7FF) {
                estimatedBytes++;
            }
        }
    }

    // Ensure the buffer has enough space
    if (lb.remaining() < estimatedBytes) {
        lb.grow(estimatedBytes);
    }

    // Write the UTF-8 encoded bytes
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            lb.writeByte((byte) c);
        } else if (c <= 0x7FF) {
            lb.writeByte((byte) (0xC0 | (c >> 6)));
            lb.writeByte((byte) (0x80 | (c & 0x3F)));
        } else {
            lb.writeByte((byte) (0xE0 | (c >> 12)));
            lb.writeByte((byte) (0x80 | ((c >> 6) & 0x3F)));
            lb.writeByte((byte) (0x80 | (c & 0x3F)));
        }
    }

    return lb;
}

