    if (constantPoolEntryIndex < 1 || constantPoolEntryIndex >= constantPoolSize) {
        throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
    }
    classFileBuffer.position(constantPoolEntryIndex);
    int tag = classFileBuffer.get() & 0xFF;
    if (tag != CONSTANT_Utf8) {
        throw new IllegalArgumentException("Not a CONSTANT_Utf8 entry at index: " + constantPoolEntryIndex);
    }
    int length = classFileBuffer.getChar();
    if (length > charBuffer.length) {
        throw new IllegalArgumentException("Char buffer is too small to hold the UTF-8 string");
    }
    for (int i = 0; i < length; i++) {
        charBuffer[i] = classFileBuffer.getChar();
    }
    return new String(charBuffer, 0, length);
}

