protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    if (tour.isEmpty()) {
        return new GraphPath<>(graph, null, null);
    }

    // Find a starting vertex
    E firstEdge = tour.iterator().next();
    V start = graph.getEdgeSource(firstEdge);
    V current = start;

    GraphPath<V,E> path = new GraphPath<>(graph, start, start);
    Set<E> usedEdges = new HashSet<>(tour);

    while (!usedEdges.isEmpty()) {
        E nextEdge = null;
        for (E edge : usedEdges) {
            if (graph.getEdgeSource(edge).equals(current)) {
                nextEdge = edge;
                break;
            } else if (graph.getEdgeTarget(edge).equals(current)) {
                // For undirected graphs, we might need to handle this differently
                // But assuming directed or we can just pick any edge incident to current
                nextEdge = edge;
                break;
            }
        }

        if (nextEdge == null) {
            // No edge found from current vertex, try to find any edge
            // This might indicate a disconnected tour or error
            nextEdge = usedEdges.iterator().next();
        }

        V nextVertex;
        if (graph.getEdgeSource(nextEdge).equals(current)) {
            nextVertex = graph.getEdgeTarget(nextEdge);
        } else {
            nextVertex = graph.getEdgeSource(nextEdge);
        }

        path.append(nextEdge, nextVertex);
        usedEdges.remove(nextEdge);
        current = nextVertex;
    }

    return path;
}

